import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(9,1,{
 title:'从全注意力到 KDA：历史信息放在哪里',summary:'先比较保存全部历史与维护一个摘要，再认识 Kimi Delta Attention 的门控与误差修正。',prerequisites:['w2-l2','w2-l3','w8-l3'],
 terms:[T('KV cache','生成时保留此前位置的键和值，避免每次重新计算它们。','序列越来越长时，需要保存的历史通常也增长。'),T('递归状态 recurrent state','每一步把旧状态和新输入合成新状态，供以后读取。','用固定形状的记忆摘要承接历史，而不是保存每个原始位置。'),T('线性注意力','通过改变注意力计算形式，使序列计算或状态存储具有不同增长规律的一类方法。','不是把标准 softmax Attention 原封不动地变便宜，也不是所有方法效果相同。'),T('KDA，Kimi Delta Attention','Kimi Linear 中采用的门控 Delta Attention 机制，利用递归记忆和细粒度门控组织信息。','需要结合矩阵状态、写入修正和读取方式理解，不能用普通标量递推冒充其公式。')],
 sections:[P('第 1 步：全注意力如何读取历史','标准因果注意力在每个新位置比较当前查询与历史键，再读取历史值。保留 KV cache 能减少重复计算，但历史位置增加时，缓存和读取工作也会增长。','如果任务需要精确找回很久以前的某个细节，保留独立历史有其优势；代价是长序列资源压力。讨论结构时要同时考虑任务需求与资源。'),P('第 2 步：改成维护一个摘要','最简单的递归演示是 s_t=0.8*s_(t−1)+x_t。旧信息逐步衰减，新信息加入。状态大小不随历史长度增长，但原始历史可能无法精确还原。','这个标量式只解释“维护状态”的思想，不是 KDA。真实方法的记忆可为矩阵，读取和写入由输入相关的向量及门控控制。'),P('第 3 步：Delta 更新为什么叫修正','Delta 类记忆更新可以先用当前键从已有记忆估计一个值，再根据目标值与估计值的差进行修正，而非只不断叠加新内容。门控则控制旧信息如何保留或遗忘。','KDA 使用更细粒度的门控设计，具体状态维度、归一化和高效计算应以论文与实际实现为准。Kimi Linear 还涉及混合架构等整体设计，引用一个 KDA 层不等于完整复现整个模型。'),P('第 4 步：判断是否适合你的世界模型','长视频历史可能适合递归状态，但要验证精确信息保持、状态容量、实际吞吐以及任务质量。理论复杂度低不保证短序列更快，更不保证所有任务都更准。','在 OmniFM 中要检查实际导入的层、层数、状态传递接口和运行配置。先确认这次训练用了哪个分支，再解释它如何学习；不能只在依赖列表看到 KDA 就下结论。')],
 worked:{title:'一个写入与遗忘的玩具记忆',steps:['初始 s=0，第一个输入 1：s=1。','后续输入都是 0，状态依次为 0.8、0.64、0.512。','历史影响仍存在，但逐步变小，且不能从这一个数还原所有历史。','真实 KDA 需进一步检查矩阵状态与输入相关门控；这个演示只用于理解资源与记忆取舍。'],takeaway:'历史能存在多久、能保留什么、需要多少资源，是三项不同问题。'},
 example:{code:'state = 0.0\nvalues = []\nfor x in [1.0, 0.0, 0.0, 0.0]:\n    state = 0.8*state+x\n    values.append(round(state, 3))\nprint(values)',output:'[1.0, 0.8, 0.64, 0.512]',explanation:'标量递推不是 KDA 实现，也没有进行训练；它提供读论文前的状态直觉。'},
 checks:[Q('固定大小状态是否意味着可以无损记住任意长历史？','一个有限摘要能否保留所有原始细节？','不能据此保证。需要评测容量、遗忘和精确检索等任务性质。',1),Q('项目引入 KDA 层，就等于复现完整 Kimi Linear 吗？','整体架构还包含哪些选择？','不等于。层类型、混合方式、训练目标、规模和实现配置都需核对。',2)],
 practice:{title:'做一张注意力与状态的对照表',steps:[A('列全注意力需要保留的历史与递归方法保留的状态。','区分独立历史位置和压缩摘要。','不要把“线性”理解为没有损失或没有容量限制。'),A('阅读 KDA 原论文摘要和架构图，记录三个尚需代码验证的接口问题。','问题具体到状态形状、更新或读取位置。','本课不要求仅凭摘要重写高效内核。'),A('在项目配置中确认当前是否选择了 KDA 分支。','提供配置键、类构造位置和运行证据。','源码存在不等于这次执行过。')]},sources:[S.kda,S.transformer]
}),
L(9,2,{
 title:'detach 与 reset：记忆可以继续，梯度可以停下',summary:'把状态数值、计算历史和参数更新时间放在三条线上，避免把三个窗口混为一谈。',prerequisites:['w9-l1','w4-l2','w1-l2'],
 terms:[T('计算图 computation graph','记录运算依赖，以便从损失反向计算参数梯度的结构。','保存中间运算会占内存，因此无限延长历史通常不现实。'),T('detach','得到保留当前数值但与过去求导历史分离的张量。','状态可以继续参与下一段前向，但梯度不再跨过该边界。'),T('reset','根据任务约定重新初始化状态，通常清零。','进入完全独立的新轨迹时，可能需要丢弃前一条轨迹的记忆。'),T('TBPTT 截断时间反向传播','把序列反向传播限制在有限时间窗口内的训练方式。','可以跨更长历史保留状态数值，同时限制梯度跨越的段数。'),T('chunk 数据块','为了加载、计算或训练而切分的一段序列。','文件或 chunk 边界不一定是环境轨迹结束。')],
 sections:[P('第 1 步：先把数值和历史分开','一个状态值可以是 0.512，同时计算图还记着它怎样由前三步得到。前向使用这个数值，反向则利用运算历史计算早先参数的贡献。两者相关但不是同一对象。','detach 保留数值，却截断之前的求导连接；reset 改变数值本身。把 detach 当成“清空记忆”，会误判模型实际可用的历史。'),P('第 2 步：理解为什么需要截断','对很长序列保留完整计算图，激活和中间状态可能占用大量内存。TBPTT 在指定边界停止更早的反向传播，使训练可执行。','代价是后面的损失不能通过被截断的路径直接调整更早的计算。模型仍可能读取旧状态带来的信息，但学习这些长程依赖的梯度路径受限。'),P('第 3 步：把三个时钟分别写出来','记忆边界：什么时候 reset；梯度窗口：什么时候 detach 或完成一段反向；更新间隔：累积多少梯度后执行 optimizer.step。这三者可以不同，但实现必须保证计算图和参数更新顺序合法。','例如状态跨整条轨迹保留，每两个 chunk 反向后 detach，每四个这样的窗口累积后更新一次。要按有效目标正确归一化，且不能在仍需反向的旧计算图中任意原地改参数。'),P('第 4 步：边界来自数据语义','连续视频的文件切分可以只表示存储分块，未必应该 reset；两个完全独立 episode 拼接通常需要明确重置。episode 指一段完整交互或轨迹。','逐项审查 loss mask、memory update mask 和 reset mask：分别控制哪些位置计分、哪些位置更新状态、何时重置。它们名字相似但不能互相替代。')],
 worked:{title:'同一个状态值遇到两种边界',steps:['边界前状态为 0.8。','detach 后前向数值仍为 0.8，过去梯度连接被切断。','reset 后数值设为 0，后续前向不再读取旧状态。','梯度累积 8 次后更新参数，既不自动决定状态何时清零，也不决定每次反向跨多长。'],takeaway:'说“窗口大小”时，必须说明是状态、梯度还是优化器窗口。'},
 example:{code:'state = 0.8\ndetached_value_demo = state\nreset_value = 0.0\nprint("value after detach conceptually", detached_value_demo)\nprint("value after reset", reset_value)\nprint("chunks per parameter update", 2*4)',output:'value after detach conceptually 0.8\nvalue after reset 0.0\nchunks per parameter update 8',explanation:'普通 Python 浮点没有自动求导图，这段只演示数值区别。真实 PyTorch 使用 state.detach()；应另查 grad_fn 或反向依赖验证截断。'},
 checks:[Q('detach 后还能使用前面输入留下的信息吗？','状态数值有没有被清空？','通常可以。数值保留，但后续损失不能沿被切断的计算图传回更早步骤。',0),Q('每 8 个 chunk 更新一次参数，是否说明反向也跨 8 个 chunk？','更新间隔与 detach 位置是否必须一致？','不一定。可能把多个较短反向窗口的梯度累积后统一更新。',2)],
 practice:{title:'把三种边界画在同一条时间线上',steps:[A('用记忆实验改变梯度窗口，不改 reset。','状态数值保持不变，图示梯度范围变化。','这是机制演示，不是实际梯度测量。'),A('改 reset 间隔，观察状态数值。','旧信息被清空，与只改梯度窗口不同。','先确定哪些边界代表独立轨迹。'),A('完成 memory-boundary 练习，并标注哪些字段是模拟计数。','能区分数值、历史窗口与优化步数。','不要把练习中的历史计数当成真实 autograd 图。')]},links:[{label:'记忆与梯度窗口实验',href:'#/labs/memory'},{label:'记忆边界练习',href:'#/code/memory-boundary'}],sources:[S.torch,S.kda]
}),
L(9,3,{
 title:'阅读 OmniFM：追踪一条样本和一次参数更新',summary:'用明确的阅读顺序建立项目地图，区分支持的功能、选中的配置和真正执行的路径。',prerequisites:['w9-l2','w8-l3','w3-l3'],
 terms:[T('入口 entrypoint','启动训练并组织参数、数据、模型和循环的程序。','命令里的脚本或模块是寻找真实路径的起点。'),T('配置覆盖','命令行、配置文件和默认值合并后决定实际参数的过程。','文件写了值 A，但命令行可能覆盖为 B。'),T('运行证据','能说明某个分支实际执行过的日志、配置快照、调用记录或断点观察。','类定义存在仅说明支持它，不能证明当前运行用了它。'),T('数据契约','模块之间对字段、形状、单位和边界的共同约定。','batch 中动作对应哪个时间、哪些位置有效、状态何时重置。')],
 sections:[P('第 1 步：从启动命令找有效配置','先记录实际运行命令、提交版本、配置文件和命令行覆盖。沿入口找参数解析与合并逻辑，输出最终配置。若你还不知道公司训练命令，就先做静态代码地图，不把推测写成运行事实。','这里不会宣称某个默认配置就是你们当前正在训练的配置。进入真实工程后，这个区分比记住一堆类名更重要。'),P('第 2 步：沿一条样本穿过系统','从原始轨迹开始，追踪切片、预处理、编码、组 batch、送入模型、构造目标与 loss。每到一个接口写下字段名和 shape，特别标记时间对齐与有效位置。','把视觉塔、codec、连接层和动态主干分别列出来。记录哪些冻结、哪些训练，输入是否有噪声，状态是否跨 chunk 传递。'),P('第 3 步：沿一份梯度回到参数','从最终标量 loss 反向找它由哪些位置和分量汇总，分母是什么，然后找到 backward、裁剪、梯度同步、optimizer.step 和清零的位置。','对一个确定应更新的参数，检查它是否在优化器参数组里，以及一步更新前后的差异。对冻结组件检查不更新；不能仅凭 requires_grad 名称推断所有实际行为。'),P('第 4 步：单独审查记忆与存档','对 reset、detach、memory update 的每个条件标记数据语义。再看 checkpoint 保存哪些训练状态、数据位置和递归状态，恢复时是否真的读取。','在公司环境中运行前，先用小数据和已确认的运行配置。只读源码不等于已经验证训练正确；报告应把“代码显示”“本次配置选择”“运行观察到”三种证据分开。'),P('第 5 步：把阅读产物变成可复查文件','交付一个入口图、一张 batch 字段表、一条更新时序和一张未知项清单。每个结论附文件位置或日志位置。这样你下次调参数时知道它影响的是哪段路径。','公司源码和日志留在公司允许的环境中；课程实验手记可以只记录抽象问题和脱敏结论，公开学习仓库不需要复制内部实现。')],
 worked:{title:'同一个 KDA 结论的三种证据等级',steps:['“代码仓库有 KDA 类”：证明存在支持。','“有效配置选择该类”：证明配置意图。','“构造日志/断点显示该类被实例化，并观察到状态传递”：支持本次运行确实走这条路径。','三者分别记录，遇到冲突就继续追踪覆盖、注册表与条件分支。'],takeaway:'理解真实训练项目，要把静态源码、有效配置和动态证据对齐。'},
 example:{code:'trace = {\n    "source_supports_kda": True,\n    "effective_config_verified": False,\n    "runtime_path_observed": False,\n}\nconfirmed = trace["effective_config_verified"] and trace["runtime_path_observed"]\nprint("current run confirmed", confirmed)',output:'current run confirmed False',explanation:'字段是阅读记录示意，不是对你当前 OmniFM 训练运行的检测结果。'},
 checks:[Q('找到一个 KDA 类定义，能否断言当前训练启用了它？','还缺有效配置和实际路径证据。','不能。还需查配置合并、模型构造和运行证据。',0),Q('为什么不能把 loss mask 当成 reset mask？','前者决定计分，后者改变状态数值。','它们控制不同操作，复用会造成错误监督或错误记忆边界。',3)],
 practice:{title:'完成第一份 OmniFM 训练阅读报告',steps:[A('在本机 ~/Code/OmniFM 中从 README 和启动脚本找入口，使用 rg 查找配置加载、forward、backward 和 optimizer.step。','得到带文件位置的阅读路线。','当前运行命令未知时明确标注，不猜生产配置。'),A('填写 batch→模型→目标→loss→更新的接口表。','每个箭头都有形状、数据来源和边界说明。','看不到运行 shape 时先写符号维度，后续用日志确认。'),A('为状态与恢复各列两项需要小实验验证的问题。','问题具体、可观察，并有预期结果。','未经允许不启动大规模公司训练；先使用团队已有的小规模验证环境。')]},sources:[S.kda,S.checkpoint,S.repro]
})];
